<?php
define('CSRFCHECK_WITH_TOKEN',1);
require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';
require_once __DIR__.'/../lib/main.lib.php';
require_once __DIR__.'/../class/OperationsSopService.class.php';
require_once DOL_DOCUMENT_ROOT.'/custom/chinaplanetcustomercenter/lib/admin_shell.lib.php';
cpo_require($user,'category');
$langs->load('chinaplanetoperations@chinaplanetoperations');
$contentLang=cpo_content_language();$service=new OperationsSopService($db);$action=GETPOST('action','aZ09');$id=GETPOSTINT('id');
try {
    if($action==='save'){
        $labels=GETPOST('label','array');$descriptions=GETPOST('description','array');$translations=array();
        foreach(OperationsSopService::supportedLanguages() as $code=>$meta)$translations[$code]=array('label'=>trim(strip_tags((string)($labels[$code]??''))),'description'=>trim(strip_tags((string)($descriptions[$code]??''))));
        $service->saveCategory(array('code'=>GETPOST('code','alphanohtml'),'position'=>GETPOSTINT('position')),$translations,(int)$user->id,$id);setEventMessages($langs->trans('SettingsSaved'),null,'mesgs');$id=0;
    } elseif($action==='toggle'){$service->setCategoryStatus($id,GETPOSTINT('status'),(int)$user->id);setEventMessages($langs->trans('SettingsSaved'),null,'mesgs');}
} catch(Throwable $e){setEventMessages($e->getMessage(),null,'errors');}
$rows=$service->getCategories($contentLang,true);$edit=null;if($id)foreach($rows as $row)if((int)$row['rowid']===$id)$edit=$row;
$morecss=array(cpo_asset('/custom/chinaplanetoperations/css/operations.css'),cpcc_admin_shell_asset('/custom/chinaplanetcustomercenter/css/admin_dashboard.css'));llxHeader('',$langs->trans('SopCategories'),'','',0,0,array(),$morecss);cpcc_admin_shell_open('sop',$langs->trans('SopCategories'),'AR · EN · ZH','fa-book-open');
?>
<main class="cpo-page"><section class="cpo-hero"><div><span class="cpo-eyebrow">MULTILINGUAL TAXONOMY</span><h1><?php echo $langs->trans('SopCategories'); ?></h1><p>AR · EN · ZH</p></div><div><?php echo cpo_language_switcher($contentLang); ?><div class="cpo-actions" style="margin-top:8px"><a class="button" href="index.php?content_lang=<?php echo urlencode($contentLang); ?>"><?php echo $langs->trans('BackToLibrary'); ?></a></div></div></section>
<section class="cpo-form-section"><h2><?php echo $langs->trans($edit?'EditCategory':'AddCategory'); ?></h2><form method="post"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo $edit?(int)$edit['rowid']:0; ?>"><input type="hidden" name="content_lang" value="<?php echo dol_escape_htmltag($contentLang); ?>"><div class="cpo-category-form"><label class="cpo-field"><span><?php echo $langs->trans('CategoryCode'); ?> *</span><input required name="code" value="<?php echo dol_escape_htmltag($edit['code']??''); ?>" placeholder="factory_audit"></label><label class="cpo-field"><span><?php echo $langs->trans('Position'); ?></span><input type="number" name="position" value="<?php echo dol_escape_htmltag($edit['position']??'100'); ?>"></label><?php foreach(OperationsSopService::supportedLanguages() as $code=>$meta){$tr=$edit['translations'][$code]??array();?><div class="cpo-field wide" dir="<?php echo $meta['dir']; ?>"><span><?php echo dol_escape_htmltag($meta['label']); ?> *</span><input required name="label[<?php echo $code; ?>]" value="<?php echo dol_escape_htmltag($tr['label']??''); ?>"><textarea name="description[<?php echo $code; ?>]" rows="2" placeholder="Description"><?php echo dol_escape_htmltag($tr['description']??''); ?></textarea></div><?php } ?></div><div class="cpo-form-actions"><button class="button button-save"><?php echo $langs->trans('Save'); ?></button><?php if($edit){ ?><a class="button" href="categories.php?content_lang=<?php echo urlencode($contentLang); ?>"><?php echo $langs->trans('Reset'); ?></a><?php } ?></div></form></section>
<section class="cpo-panel"><div class="cpo-panel-head"><h2><?php echo $langs->trans('AvailableCategories'); ?> <span class="badge"><?php echo count($rows); ?></span></h2></div><div class="div-table-responsive"><table class="cpo-table"><thead><tr><th><?php echo $langs->trans('Position'); ?></th><th><?php echo $langs->trans('CategoryCode'); ?></th><th>EN</th><th>AR</th><th>ZH</th><th><?php echo $langs->trans('Status'); ?></th><th></th></tr></thead><tbody><?php foreach($rows as $row){ ?><tr><td><?php echo (int)$row['position']; ?></td><td><code><?php echo dol_escape_htmltag($row['code']); ?></code></td><?php foreach(array('en_US','ar_SA','zh_CN') as $code){ ?><td dir="<?php echo $code==='ar_SA'?'rtl':'ltr'; ?>"><?php echo dol_escape_htmltag($row['translations'][$code]['label']??'—'); ?></td><?php } ?><td><?php echo $langs->trans((int)$row['status']?'Active':'Archived'); ?></td><td><a class="button smallpaddingimp" href="?id=<?php echo (int)$row['rowid']; ?>&content_lang=<?php echo urlencode($contentLang); ?>"><?php echo $langs->trans('EditCategory'); ?></a> <form method="post" class="cpo-inline-form"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?php echo (int)$row['rowid']; ?>"><input type="hidden" name="status" value="<?php echo (int)$row['status']?0:1; ?>"><input type="hidden" name="content_lang" value="<?php echo dol_escape_htmltag($contentLang); ?>"><button class="button smallpaddingimp"><?php echo $langs->trans((int)$row['status']?'Archive':'Restore'); ?></button></form></td></tr><?php } ?></tbody></table></div></section></main>
<?php cpcc_admin_shell_close();llxFooter();$db->close(); ?>
